function openBookings(id,filter='Все'){selected=id;bookingFilter=filter;go('manage')}
function changeBooking(i,status){const e=current(),p=bookings(e.id)[i];if(!p||e.cancelled||e.draft||!['Подтверждено','Отклонено','Ожидает'].includes(status))return;if(p.status===status){closeModal();return}p.status=status;bookingSystem(e,userKey(p.name),status==='Подтверждено'?'Запись подтверждена':status==='Отклонено'?'Запись отклонена':'Запись ожидает подтверждения');e.going=bookings(e.id).filter(x=>['Подтверждено','Посетил'].includes(x.status)).length;closeModal();render();if(typeof window.setTimeout==='function')toast('Статус записи обновлён')}
function pendingOrgEvents(){return events.filter(e=>e.own&&!e.draft&&!e.cancelled&&pending(e.id)>0).sort((a,b)=>pending(b.id)-pending(a.id)||a.id-b.id)}
function syncOrgEventUrl(){if(mode!=='org'||!window.location?.href||!window.history?.replaceState)return;const url=new URL(window.location.href);if(activeScreen==='orgEvents'){url.searchParams.set('view','events');if(orgFilter==='Ждут подтверждения')url.searchParams.set('waitApproval','true');else url.searchParams.delete('waitApproval')}else if(!['manage','participants','edit','chat','directChat'].includes(activeScreen)){url.searchParams.delete('view');url.searchParams.delete('waitApproval')}window.history.replaceState(null,'',url.toString())}
