function directChat(){const k=dmSelected,[o,u]=parsePair(k),name=dmName(k),self=mode==='org'?o:u;return '<section class="chat direct-chat"><div class="pageTitle"><div class="row"><button class="back" onclick="go(dmBack)">‹</button><span class="avatar">'+esc(name[0])+'</span><div><h3>'+esc(name)+'</h3><small>'+(mode==='org'?'Участник':'Организатор')+'</small></div></div></div><div class="messages" id="messages">'+((dmThreads[k]||[]).map(m=>{if(m.type==='system'){const e=events.find(x=>x.id===m.event);return '<div class="dm-system"><small>Уведомление Livenout</small><b>'+esc(m.text)+'</b><span>'+esc(e?.title||'Событие')+'</span>'+(e?'<button onclick="openDirectEvent('+e.id+')">Открыть событие ›</button>':'')+'<small>'+esc(m.time)+'</small></div>'}return '<div class="bubble '+(m.sender===self?'mine':'')+'"><p>'+esc(m.text)+'</p><small>'+esc(m.time)+'</small></div>'}).join('')||'<div class="empty">Напишите первое сообщение.</div>')+'</div><form class="chatinput" onsubmit="event.preventDefault();sendDirect(this.msg.value)"><input name="msg" required placeholder="Напишите сообщение…"><button class="primary" aria-label="Отправить">➤</button></form></section>'}
