const page=(title,body,back='')=>'<section class="page"><div class="pageTitle"><div class="row">'+(back?'<button class="back" aria-label="Назад" onclick="go(\''+back+'\')">‹</button>':'')+'<h1>'+title+'</h1></div></div>'+body+'</section>';
