const cover=e=>'<div class="cover" style="background-color:'+e.color+';'+(e.image?'background-image:linear-gradient(0deg,#0004,transparent),url('+e.image+')':'')+'"><span>'+esc(e.cat)+'</span></div>';
const progress=e=>e.goal?'<div><div class="row between"><small>All or Nothing · '+e.going+' / '+e.goal+' записались</small><b>'+Math.min(100,Math.round(e.going/e.goal*100))+'%</b></div><div class="progress"><b style="width:'+Math.min(100,e.going/e.goal*100)+'%"></b></div><small>Набор до '+esc(e.deadline||'начала события')+'</small></div>':'<small>'+e.going+' участников · обычная запись</small>';
const like=e=>'<button aria-label="Избранное" class="heart" onclick="event.stopPropagation();toggleLike('+e.id+')">'+(liked.has(e.id)?'♥':'♡')+'</button>';
function card(e){return '<article class="event '+(e.goal?'promoted':'')+'" onclick="openEvent('+e.id+')"><div class="row between"><span class="eventTitle">'+esc(e.title)+'</span>'+like(e)+'</div><div class="eventInfo">'+cover(e)+'<div><span class="tag">'+esc(e.cat)+'</span> <small>'+esc(e.lang)+'</small><p class="desc">'+esc(e.desc)+'</p><b>'+ (e.price?e.price+' zł':'Бесплатно')+'</b></div></div><div class="eventFoot"><span>◷ '+esc(e.date)+'</span><span>⌖ '+e.km+' km</span></div>'+(e.goal?progress(e):'')+'</article>'}
function switchRole(r){if(!['org','user'].includes(r)||r===mode)return;window.location.href=mode==='org'?'../?v=28':'org/?v=33'}
