function applyFilter(key,value){if(key==='day')day=value;if(key==='cat')cat=value;if(key==='lang')lang=value;render()}
function pickDay(v){day=v;render()}
function setSheet(n){sheetLevel=n;const el=$('#sheet');if(!el)return;const max=$('#view').clientHeight*.9;sheetHeight=[59,Math.min(260,max),max][n];el.style.height=sheetHeight+'px';$('#mapcount').style.bottom=sheetHeight+9+'px';$('#mapcount').style.opacity=n===2?'0':'1';$('#mapcount').style.pointerEvents=n===2?'none':'auto';el.dataset.level=String(n)}
function openCatalog(){catalogTop=0;go('catalog')}
function searchEvents(){query=$('#smart').value.trim();openCatalog()}
function filterModal(){modal('Фильтры','<form class="form" onsubmit="event.preventDefault();day=this.day.value;cat=this.cat.value;lang=this.lang.value;free=this.free.checked;community=this.community.checked;closeModal();render()"><label>Дата<select name="day">'+opts(['Все','Сегодня','Завтра','Выходные','На неделе'],day)+'</select></label><label>Категория<select name="cat">'+opts(['Все','Игры','Искусство','Развлечения','Сообщество'],cat)+'</select></label><label>Язык<select name="lang">'+opts(['Все','RU','UK','BY','PL','EN'],lang)+'</select></label><label class="check"><input name="free" type="checkbox" '+(free?'checked':'')+'>Только бесплатные</label><label class="check"><input name="community" type="checkbox" '+(community?'checked':'')+'>От сообщества</label><button class="primary">Показать события</button>'+btn('Сбросить','resetFilters()',true)+'</form>')}
function resetFilters(){query='';day=cat=lang='Все';free=community=false;closeModal();render()}
function opts(arr,v){return arr.map(x=>'<option '+(x===v?'selected':'')+'>'+esc(x)+'</option>').join('')}
function home(){const list=filtered(),all=day==='Все'&&cat==='Все'&&lang==='Все'&&!free&&!community&&!query;const pins=all?[[37,25,'🎵'],[34,47,'36'],[50,45,'187'],[48,53,'13'],[88,62,'🎨']]:list.map((e,i)=>[[37,34,50,48,88][i%5],[25,47,45,53,62][i%5],'1']);return '<section class="map" id="map"><div class="maplayer" id="maplayer" style="transform:translate('+mapX+'px,'+mapY+'px) scale('+zoom+')">'+pins.map(([x,y,t])=>'<button class="marker '+(isNaN(Number(t))?'point':'')+'" style="top:'+y+'%;left:'+x+'%" onclick="openCatalog()">'+t+'</button>').join('')+'<i class="mylocation"></i></div></section><div class="maptop"><div class="chips fastfilters">'+chip('Следующие 7 дней',day==='7days',"pickDay(day==='7days'?'Все':'7days')")+chip('Завтра',day==='Завтра',"pickDay(day==='Завтра'?'Все':'Завтра')")+chip('Сегодня',day==='Сегодня',"pickDay(day==='Сегодня'?'Все':'Сегодня')")+chip('Бесплатно',free,'free=!free;render()')+'</div><div class="row between sourcebar"><div class="sourceToggle">'+chip('Все события',!community,'community=false;render()')+chip('От сообщества',community,'community=true;render()')+'</div><button class="icon filterround" aria-label="Фильтры" onclick="filterModal()">'+ico('filter')+'</button></div></div><button id="mapcount" class="mapcount" onclick="openCatalog()">События в этой области <span>('+(all?238:list.length)+')</span></button><section class="sheet" id="sheet"><div class="grip" id="grip" aria-label="Размер шторки" role="button" tabindex="0"></div><div class="sheethead" onclick="if(sheetLevel===0)setSheet(1)"><h2><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="#72a9f6" stroke-width="2"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="3"/></svg> События рядом</h2></div><div class="sheetbody stack"><div class="categoryrail">'+[['🎉','Развлечения','Вечеринки, развлекательные программы и яркие события'],['🎵','Музыка','Концерты, живая музыка и музыкальные события'],['🎨','Искусство','Творческие встречи и мастер-классы'],['🎲','Игры','Настольные игры и встречи в компании']].map(([i,t,d])=>'<button class="categorytile" onclick="cat=\''+t+'\';openCatalog()"><div class="row"><span>'+i+'</span><b>'+t+'</b></div><p>'+d+'</p></button>').join('')+'</div><div class="smartlabel"><span>✧</span> Умный поиск</div><form class="search" onsubmit="event.preventDefault();searchEvents()"><input id="smart" placeholder="Уютный творческий вечер" value="'+esc(query)+'"><button aria-label="Поиск">➤</button></form><div class="sheetExtra stack">'+list.map(card).join('')+'</div></div></section>'}
function catalog(){const list=filtered();return '<div class="feedwrap"><div class="feedbar"><button onclick="go(\'home\')">‹ Изменить область поиска</button><div class="row"><button class="icon" style="color:'+(feedMode==='list'?'#ff8a3d':'#a0a6b8')+'" onclick="feedMode=\'list\';catalogTop=0;render()" aria-label="Список">'+ico('list')+'</button><button class="icon" style="color:'+(feedMode==='large'?'#ff8a3d':'#a0a6b8')+'" onclick="feedMode=\'large\';catalogTop=0;render()" aria-label="Карточки">▣</button><button class="icon" onclick="filterModal()" aria-label="Фильтры">'+ico('filter')+'</button></div></div><div id="feedcontent" class="feedcontent '+(feedMode==='large'?'largefeed':'')+'">'+(!list.length?'<div class="empty">Ничего не найдено.<br><br>'+btn('Оставить запрос','requestModal()')+btn('Сбросить фильтры','resetFilters()',true)+'</div>':feedMode==='list'?'<div class="list">'+list.map(e=>'<div id="evt-'+e.id+'">'+card(e)+'</div>').join('')+'</div>':list.map(e=>'<article class="feeditem" id="evt-'+e.id+'">'+cover(e)+'<div class="row between"><h2>'+esc(e.title)+'</h2>'+like(e)+'</div><div class="date">'+esc(e.date)+' · '+esc(e.place)+'</div><div class="row"><span class="tag">'+esc(e.cat)+'</span><small>'+esc(e.lang)+'</small></div><p class="muted">'+esc(e.desc)+'</p>'+progress(e)+'<div class="row">'+btn('Детали','openEvent('+e.id+')',true)+btn('Чат','openChat('+e.id+')',true)+'</div>'+btn(joined.has(e.id)?'Вы записаны':'Присоединиться','selected='+e.id+';joinModal()')+'</article>').join(''))+'</div></div>'}
function detail(){const e=current();return page('', '<div class="detailcover">'+cover(e).replace('class="cover"','class="cover" style-dummy=""').replace('min-height:120px','')+'</div><div class="row between"><h1>'+esc(e.title)+'</h1>'+like(e)+'</div><br>'+progress(e)+'<div class="stack section"><div class="fact">◷ <div><small>Дата и время</small><strong>'+esc(e.date)+'</strong></div></div><div class="fact">⌖ <div><small>Место</small><strong>'+esc(e.place)+'</strong></div></div><button class="fact" onclick="go(\'organizer\')"><span class="avatar">EH</span><div style="text-align:left"><small>Организатор</small><strong>'+ (e.own?'Event Hunter':'Warsaw Community')+'</strong></div><span style="margin-left:auto">›</span></button></div><h2 class="section">О событии</h2><div class="row"><span class="tag">'+esc(e.cat)+'</span><small>'+esc(e.lang)+'</small></div><p style="margin:12px 0">'+esc(e.desc)+'</p><b>'+ (e.price?e.price+' zł':'Бесплатно')+'</b><div class="sticky stack">'+btn(mode==='org'&&e.own?'Управление':joined.has(e.id)?'Вы записаны · Подробнее':'Участвовать',mode==='org'&&e.own?'manage('+e.id+')':'joinModal()')+(mode==='user'?btn('Написать организатору','contactOrganizer()',true):'')+btn('Чат события','openChat('+e.id+')',true)+btn('Поделиться','shareEvent()',true)+'</div>',returnScreen||'home')}
function joinModal(){const e=current();if(joined.has(e.id)){modal('Ваша запись','<div class="stack"><h3>'+esc(e.title)+'</h3><span class="status '+(e.goal&&e.going<e.goal?'wait':'')+'">'+(e.goal&&e.going<e.goal?'Ожидаем набора':'Запись подтверждена')+'</span>'+btn('Чат события','openChat('+e.id+')')+btn('Отменить участие','cancelJoin()',true)+'</div>');return}modal('Подтверждение участия','<form class="form" onsubmit="event.preventDefault();confirmJoin()"><h3>'+esc(e.title)+'</h3><small>'+esc(e.date)+' · '+esc(e.place)+'</small>'+progress(e)+'<div class="fact"><strong>'+(e.price?e.price+' zł':'Бесплатно')+'</strong><small>1 место</small></div>'+(e.goal?'<p class="notice">Событие состоится, если наберётся '+e.goal+' участников. </p>':'')+'<label class="check"><input required type="checkbox">Я принимаю условия участия.</label><button class="primary">Подтвердить запись</button></form>')}
function confirmJoin(){const e=current();if(!joined.has(e.id)){joined.add(e.id);e.going++;bookingSystem(e,demoUser,'Новая заявка на участие');}go('my');toast('Вы записаны')}
function cancelJoin(){const e=current();if(joined.delete(e.id)){e.going=Math.max(0,e.going-1);bookingSystem(e,demoUser,'Участник отменил запись');}go('my');toast('Запись отменена')}
function shareEvent(){modal('Поделиться событием','<p class="muted">Ссылка на событие</p><p style="word-break:break-all;margin:10px 0">https://livenout.example/events/'+selected+'</p>'+btn('Скопировать','toast(\'Ссылка подготовлена\');closeModal()'))}
function requestModal(){modal('Запрос на мероприятие','<form class="form" onsubmit="event.preventDefault();closeModal();toast(\'Запрос сохранён\')"><label>Чем хотите заняться?<textarea required placeholder="Например, керамика на русском в выходные"></textarea></label><label>Когда<select><option>Любое время</option><option>Выходные</option><option>Будни</option></select></label><button class="primary">Оставить запрос</button><small>Прототип новой функции. Организаторы увидят агрегированный спрос.</small></form>')}
function my(){const arr=events.filter(e=>joined.has(e.id));return page('Мои события','<div class="stack">'+(arr.length?arr.map(card).join(''):'<div class="empty">Пока нет записей.</div>')+btn('Найти мероприятие','go(\'home\')',true)+'</div>')}
function favorites(){return page('Избранное','<div class="stack">'+(events.filter(e=>liked.has(e.id)).map(card).join('')||'<div class="empty">Сохраните понравившиеся события.</div>')+'</div>')}
function chats(){const arr=events.filter(e=>mode==='org'?e.own&&!e.draft&&!e.cancelled:joined.has(e.id));const group=arr.map(e=>'<button class="entry" onclick="openChat('+e.id+')"><span class="avatar">#</span><div><b>'+esc(e.title)+'</b><small>'+esc(messages[e.id]?.at(-1)?.text||'Сообщений пока нет')+'</small></div><span>›</span></button>').join('')||'<div class="empty">Пока нет чатов событий.</div>';return page('Чаты','<div class="inbox-tabs">'+chip('Личные',inboxTab==='direct',"inboxTab='direct';render()")+chip('По событиям',inboxTab==='group',"inboxTab='group';render()")+'</div><div class="stack">'+(inboxTab==='direct'?directList():group)+'</div>')}
function chat(){const e=current();return '<section class="chat"><div class="pageTitle"><div class="row"><button class="back" onclick="go(chatBack)">‹</button><div><h3>'+esc(e.title)+'</h3><small>Чат события · '+e.going+' участников</small></div></div></div><div class="messages" id="messages">'+((messages[e.id]||[]).map(m=>'<div class="bubble '+(m.mine?'mine':'')+'"><b>'+esc(m.name)+'</b><p>'+esc(m.text)+'</p><small>'+esc(m.time)+'</small></div>').join('')||'<div class="empty">Сообщений пока нет. Начните разговор!</div>')+'</div><form class="chatinput" onsubmit="event.preventDefault();sendMessage(this.msg.value)"><input name="msg" required placeholder="Напишите сообщение…"><button class="primary" aria-label="Отправить">➤</button></form></section>'}
function sendMessage(t){if(!t.trim())return;(messages[selected]??=[]).push({name:mode==='org'?'Event Hunter':'Вы',text:t,time:'Сейчас',mine:true});render();$('#messages').scrollTop=$('#messages').scrollHeight}
function notifs(){seen=true;return page('Уведомления',''+notifications.filter(n=>n.role===mode||n.role==='both').map(n=>'<button class="entry" onclick="'+(n.type==='chat'?'openChat('+n.event+')':mode==='org'&&n.type==='booking'?'openBookings('+n.event+',\'Ожидает\')':mode==='org'&&events.find(e=>e.id===n.event)?.own?'manage('+n.event+')':'openEvent('+n.event+')')+'"><span class="avatar">●</span><div><b>'+esc(n.title)+'</b><small>'+esc(n.text)+'</small><small>'+esc(n.when)+'</small></div><span>›</span></button>').join('')+btn('Настройки уведомлений','notificationSettings()',true))}

const notificationOptions={org:[['push','Push-уведомления'],['booking','Новые записи и заявки'],['cancel','Отмена записи участником'],['chat','Новые сообщения в чатах'],['bookingUpdates','Изменения статуса записей'],['aon','Статус All or Nothing'],['reminder','Напоминания о событиях']],user:[['push','Push-уведомления'],['reminder','Напоминания о событиях'],['cancel','Изменения и отмены'],['aon','Статус All or Nothing'],['chat','Новые сообщения'],['bookingUpdates','Статус записи'],['interest','События по интересам']]};
function readNotificationPrefs(){try{return JSON.parse(window.localStorage.getItem('livenout-lite-notifications-'+mode)||'{}')}catch{return {}}}
let notifPrefs=readNotificationPrefs();
function saveNotificationPrefs(form){const next={};for(const [key] of notificationOptions[mode])next[key]=!!form.elements[key].checked;notifPrefs=next;try{window.localStorage.setItem('livenout-lite-notifications-'+mode,JSON.stringify(next))}catch{}closeModal();render();toast('Настройки сохранены')}
function notificationSettings(){modal('Настройки уведомлений','<form class="form" onsubmit="event.preventDefault();saveNotificationPrefs(this)">'+notificationOptions[mode].map(([key,label])=>'<label class="notification-option"><span>'+label+'</span><input type="checkbox" name="'+key+'" '+(notifPrefs[key]!==false?'checked':'')+'></label>').join('')+'<button class="primary">Сохранить</button></form>')}

function profile(){const isOrg=mode==='org';return page(isOrg?'Профиль организатора':'Мой профиль','<div class="card row"><div class="avatar">'+(isOrg?'EH':'L')+'</div><div><h2>'+(isOrg?'Event Hunter':'livenout')+'</h2><small>'+(isOrg?'Организатор':'Участник')+'</small></div></div><h2 class="section">Аккаунт</h2><div class="stack">'+btn('Настройки уведомлений','notificationSettings()',true)+(isOrg?'<a class="secondary" href="https://livenout.com/">Полный кабинет на сайте ↗</a>':btn('Мои интересы и запросы',"go('interests')",true))+'</div>')}
function interests(){return page('Мои интересы','<div class="stack"><div class="card"><b>Керамика · Варшава</b><p class="muted">Выходные · уведомлять о новых событиях</p></div><div class="card"><b>Настольные игры</b><p class="muted">RU / UK · уведомлять о новых событиях</p></div>'+btn('Добавить запрос','requestModal()')+'</div>','profile')}
function organizer(){const e=current();return page('Организатор','<div class="card row"><span class="avatar">EH</span><div><h2>'+ (e.own?'Event Hunter':'Warsaw Community')+'</h2><small>Локальные мероприятия</small></div></div><div class="section">'+btn(followed?'Вы подписаны':'Подписаться','followed=!followed;render()',followed)+btn('Написать организатору','contactOrganizer()',true)+'</div><h2 class="section">Предстоящие события</h2><div class="stack">'+events.filter(x=>x.own===e.own).map(card).join('')+'</div>','detail')}

let dashboardPeriod='Ближайшие';
function switchDashboardPeriod(period){if(dashboardPeriod===period)return;const scroll=$('.org-dashboard.page')?.scrollTop||0;dashboardPeriod=period;render();const page=$('.org-dashboard.page');if(page)page.scrollTop=scroll}
function showOrganizerProfileStats(){modal('Просмотры профиля','<div class="stack"><div class="dash-status"><span>Всего просмотров</span><b>47</b></div><div class="dash-status"><span>Уникальных</span><b>18</b></div><div class="dash-status"><span>За 24 часа</span><b>0</b></div><div class="dash-status"><span>За 7 дней</span><b>1</b></div></div>')}
function dashboardEventTime(e){const value=e.date||'';const iso=Date.parse(value);if(Number.isFinite(iso))return iso;const m=value.toLowerCase().match(/^(\d{1,2})\s+([а-яё]+)\.?\s*(?:(\d{4})\s*)?(?:·\s*)?(\d{1,2}):(\d{2})/);if(!m)return 0;const month=['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'].indexOf(m[2].slice(0,3).replace('мая','май'));return month<0?0:Date.UTC(Number(m[3]||2026),month,Number(m[1]),Number(m[4]),Number(m[5]))}
function dashboardEventPreview(items,past=false){return [...items].sort((a,b)=>{const x=dashboardEventTime(a),y=dashboardEventTime(b);return !x&&y?1:x&&!y?-1:(past?y-x:x-y)||a.id-b.id}).slice(0,DASHBOARD_LIMIT)}
function orgDashboard(){
 const own=events.filter(e=>e.own),live=own.filter(e=>!e.draft&&!e.cancelled&&!e.completed),drafts=own.filter(e=>e.draft),past=own.filter(e=>e.completed||e.cancelled);
 const total=own.length;
 const stat=(title,val,action)=>'<button type="button" class="dash-stat" onclick="'+action+'"><span class="dash-stat-label">'+title+'</span><strong>'+val+'</strong></button>';
 const status=(title,val)=>'<div class="dash-status"><span>'+title+'</span><b>'+val+'</b></div>';
 const row=e=>'<button type="button" class="dash-event dash-event-link" onclick="manage('+e.id+')"><span class="dash-event-copy"><b>'+esc(e.title)+'</b><small>'+esc(e.date)+'</small></span><span class="dash-row-chevron" aria-hidden="true">›</span></button>';
 return '<section class="page org-dashboard">'+'<div class="dash-stats">'+stat('Активные события',live.length,'openAllOrgEvents()')+stat('Просмотры профиля',47,'showOrganizerProfileStats()')+'</div>'+'<section class="dash-panel"><h2>Ждут подтверждения</h2>'+pendingDashboardList()+'</section><section class="dash-panel"><div class="row between dash-panel-title"><h2><button type="button" class="dash-all-title" onclick="openAllOrgEvents()">Все события<span aria-hidden="true" class="dash-heading-chevron">›</span></button></h2><div class="dash-segment">'+['Ближайшие','Прошедшие'].map(p=>'<button class="'+(dashboardPeriod===p?'on':'')+'" onclick="switchDashboardPeriod(\''+p+'\')">'+p+'</button>').join('')+'</div></div>'+'<div class="dash-events-slot">'+[['Ближайшие',dashboardEventPreview(live)],['Прошедшие',dashboardEventPreview(past,true)]].map(([label,items])=>'<div class="dash-events-pane'+(dashboardPeriod===label?'':' inactive')+'" '+(dashboardPeriod===label?'':'inert aria-hidden="true"')+'>'+(items.length?items.map(row).join(''):'<p class="dash-empty">Нет событий</p>')+'</div>').join('')+'</div>'+'</section><section class="dash-panel"><h2>Статусы событий</h2>'+status('Опубликовано',live.length)+status('Состоялось',own.filter(e=>e.completed).length)+status('Не состоялось',0)+status('Отменено',own.filter(e=>e.cancelled).length)+'</section><section class="dash-panel"><h2>Следующие шаги</h2><div class="stack">'+btn('Заполнить профиль организатора',"go('profile')",true)+btn('Просмотреть организованные события',"go('orgEvents')",true)+'</div></section><section class="dash-panel"><h2>Продолжить создание</h2>'+(drafts.length?drafts.slice(0,DASHBOARD_LIMIT).map(e=>'<div class="dash-event"><div><b>'+esc(e.title)+'</b><small class="draft-label">Черновик</small></div>'+btn('Продолжить ›','selected='+e.id+';go(\'edit\')',false,true)+'</div>').join(''):'<p class="dash-empty">Нет сохранённых черновиков</p>')+'<button type="button" class="dash-text-action" onclick="openDraftEvents()">Все черновики <span aria-hidden="true">›</span></button></section></section>'
}

function orgRatings(){return page('Рейтинг и выплаты','<section class="dash-panel"><h2>Рейтинг</h2><div class="dash-status"><span>Рейтинг</span><b>Нет отзывов</b></div><div class="dash-status"><span>Отзывы</span><b>0</b></div></section><section class="dash-panel"><h2>Выплаты</h2><p class="dash-empty">Данные о выплатах недоступны в демо.</p><a class="secondary" href="https://livenout.com/">Полный кабинет на сайте ↗</a></section>')}

function orgEvents(){const arr=events.filter(e=>e.own),visible=orgFilter==='Ждут подтверждения'?pendingOrgEvents():arr.filter(e=>orgFilter==='Черновики'?e.draft:orgFilter==='Завершённые'?e.cancelled||e.completed:!e.draft&&!e.cancelled&&!e.completed);return page('Мои события','<div class="stats"><div class="stat"><small>Активные</small><strong>'+arr.filter(e=>!e.cancelled&&!e.draft&&!e.completed).length+'</strong></div><div class="stat"><small>Записи</small><strong>'+arr.reduce((s,e)=>s+e.going,0)+'</strong></div></div><div class="section chips">'+['Активные','Черновики','Завершённые','Ждут подтверждения'].map(x=>chip(x,orgFilter===x,"setOrgFilter('"+x+"')")).join('')+'</div><div class="stack">'+(visible.map(e=>'<div class="card stack"><div class="row between"><h3>'+esc(e.title)+'</h3><span class="status '+(e.goal&&e.going<e.goal?'wait':'')+'">'+(e.draft?'Черновик':e.cancelled?'Отменено':e.completed?'Состоялось':e.goal&&e.going<e.goal?'Набор':'Активно')+'</span></div><small>'+esc(e.date)+'</small>'+(pending(e.id)?'<div class="pending-event-summary">Ожидают подтверждения: '+pending(e.id)+'</div>':'')+progress(e)+btn('Управление','manage('+e.id+')')+'<div class="row">'+btn('Участники · '+e.going+(pending(e.id)?' / +'+pending(e.id):''),'openBookings('+e.id+')',true)+btn('Чат','openChat('+e.id+')',true)+'</div></div>').join('')||'<div class="empty">Нет событий в этом разделе.</div>')+btn('+ Создать событие','go(\'create\')')+'</div>')}

function bookingAction(label,action,style){return '<button type="button" class="booking-action '+style+'" onclick="'+action+'">'+label+'</button>'}
function bookingCard(p,i,locked){
 const accepted=p.status==='Подтверждено'||p.status==='Посетил',rejected=p.status==='Отклонено',cancelled=p.status==='Отменено',state=accepted?'accepted':rejected||cancelled?'rejected':'pending';
 let actions='';
 if(!locked&&!cancelled){if(!accepted)actions+=bookingAction('Принять',"changeBooking("+i+",'Подтверждено')",'accept');if(!rejected)actions+=bookingAction('Отклонить','confirmBookingCancel('+i+')','reject');}
 return '<article class="booking-person"><div class="booking-person-top"><span class="avatar">'+esc(p.name[0])+'</span><div class="booking-person-name"><b>'+esc(p.name)+'</b><span class="booking-status '+state+'">'+(accepted?'Принята':rejected?'Отклонена':cancelled?'Отменена участником':'Ожидает решения')+'</span></div><button class="booking-dm" aria-label="Написать участнику" onclick="contactParticipant('+i+')">'+ico('chat')+'</button>'+(!locked&&!cancelled&&(accepted||rejected)?'<button class="booking-more" aria-label="Другие действия: '+esc(p.name)+'" onclick="participantModal('+i+')">⋯</button>':'')+'</div>'+(actions?'<div class="booking-person-actions">'+actions+'</div>':'')+'</article>'
}
function bookingPanel(e){
 const arr=bookings(e.id),count=s=>arr.filter(p=>s==='Подтверждено'?['Подтверждено','Посетил'].includes(p.status):p.status===s).length;
 const tabs=[['Все','Все',arr.length],['Ожидает','Новые',count('Ожидает')],['Подтверждено','Принятые',count('Подтверждено')],['Отклонено','Отклонённые',count('Отклонено')]];
 if(count('Отменено'))tabs.push(['Отменено','Отменённые',count('Отменено')]);
 const shown=arr.map((p,i)=>({p,i})).filter(({p})=>(bookingFilter==='Все'||p.status===bookingFilter||bookingFilter==='Подтверждено'&&p.status==='Посетил')).sort((a,b)=>(a.p.status==='Ожидает'?0:1)-(b.p.status==='Ожидает'?0:1));
 return '<section class="event-bookings"><div class="row between"><h2>Записи <span class="booking-total">'+arr.length+'</span></h2></div><div class="event-booking-tabs">'+tabs.map(([v,t,n])=>'<button class="'+(bookingFilter===v?'on':'')+'" onclick="bookingFilter=\''+v+'\';render()">'+t+' <b>'+n+'</b></button>').join('')+'</div><div class="booking-people">'+(shown.map(({p,i})=>bookingCard(p,i,e.cancelled||e.draft)).join('')||'<div class="empty">Нет записей в этом разделе.</div>')+'</div></section>'
}
function managePage(){const e=current();return page('Управление событием','<div class="event-workspace"><div class="card event-overview"><div class="row between"><span class="status '+(e.goal&&e.going<e.goal?'wait':'')+'">'+(e.cancelled?'Отменено':e.draft?'Черновик':e.completed?'Состоялось':e.goal&&e.going<e.goal?'Идёт набор':'Опубликовано')+'</span><div class="event-card-actions"><button type="button" class="event-chat-button" aria-label="Чат события, непрочитанных: '+orgGroupUnread(e.id)+'" title="Чат события" onclick="openChat('+e.id+')">'+orgNavIcon('message-circle')+orgUnreadBadge(orgGroupUnread(e.id))+'</button><button class="event-more" aria-label="Действия с событием" onclick="eventActions()">⋯</button></div></div><h2>'+esc(e.title)+'</h2><small>'+esc(e.date)+'</small><small>'+esc(e.place)+'</small><div class="event-progress">'+progress(e)+'</div></div><div class="booking-summary"><div><b>'+e.going+'</b><small>Принято</small></div><div class="waiting"><b>'+pending(e.id)+'</b><small>Ожидают решения</small></div><div><b>'+bookings(e.id).filter(p=>p.status==='Отклонено').length+'</b><small>Отклонено</small></div></div>'+bookingPanel(e)+'</div>','orgEvents')}
function eventActions(){const e=current();modal('Действия с событием','<div class="stack">'+btn('Редактировать',"go('edit')",true)+btn('Просмотр карточки','openEvent('+e.id+')',true)+btn('Поделиться','shareEvent()',true)+btn('Отправить напоминание','reminderModal()',true)+btn('Дублировать','duplicateEvent()',true)+(!e.cancelled?btn('Отменить событие','cancelEvent()',true):'')+'</div>')}

