function bindMap(){setSheet(sheetLevel);const grip=$('#grip'),sheet=$('#sheet');let sy=0,start=0,drag=false;grip.onpointerdown=e=>{sy=e.clientY;start=sheetHeight;drag=true;sheet.classList.add('dragging');grip.setPointerCapture(e.pointerId)};grip.onpointermove=e=>{if(!drag)return;sheetHeight=Math.max(59,Math.min($('#view').clientHeight*.9,start+sy-e.clientY));sheet.style.height=sheetHeight+'px';$('#mapcount').style.bottom=sheetHeight+9+'px'};function finish(e){if(!drag)return;drag=false;sheet.classList.remove('dragging');const delta=sy-e.clientY;if(Math.abs(delta)<8)setSheet((sheetLevel+1)%3);else setSheet(Math.max(0,Math.min(2,sheetLevel+(delta>0?1:-1))))}grip.onpointerup=finish;grip.onpointercancel=()=>{drag=false;sheet.classList.remove('dragging');setSheet(sheetLevel)};grip.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setSheet((sheetLevel+1)%3)}};const map=$('#map');let startX,startY,ox,oy,moving=false;map.onpointerdown=e=>{if(e.target.closest('button'))return;startX=e.clientX;startY=e.clientY;ox=mapX;oy=mapY;moving=true;map.setPointerCapture(e.pointerId)};map.onpointermove=e=>{if(moving){mapX=Math.max(-100,Math.min(100,ox+e.clientX-startX));mapY=Math.max(-100,Math.min(100,oy+e.clientY-startY));$('#maplayer').style.transform='translate('+mapX+'px,'+mapY+'px) scale('+zoom+')'}};map.onpointerup=map.onpointercancel=()=>moving=false}
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeModal()});render();



